import json
import os
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def retrieve_json_secret(secret_id: str, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Retrieve a JSON-formatted secret from AWS Secrets Manager and parse it.

    Args:
        secret_id: The Secrets Manager secret name or ARN.
        region_name: Optional AWS region. If omitted, uses default AWS configuration.

    Returns:
        Parsed JSON object as a Python dictionary.

    Raises:
        RuntimeError: If the secret cannot be retrieved or is not valid JSON.
    """
    client_kwargs = {}
    if region_name:
        client_kwargs["region_name"] = region_name

    client = boto3.client("secretsmanager", **client_kwargs)

    try:
        response = client.get_secret_value(SecretId=secret_id)
    except (ClientError, BotoCoreError) as e:
        raise RuntimeError(f"Failed to retrieve secret '{secret_id}': {e}") from e

    secret_string = response.get("SecretString")
    if secret_string is None:
        secret_binary = response.get("SecretBinary")
        if secret_binary is None:
            raise RuntimeError(f"Secret '{secret_id}' did not contain a retrievable value")
        if isinstance(secret_binary, bytes):
            secret_string = secret_binary.decode("utf-8")
        else:
            secret_string = bytes(secret_binary).decode("utf-8")

    try:
        parsed = json.loads(secret_string)
    except json.JSONDecodeError as e:
        raise RuntimeError(f"Secret '{secret_id}' is not valid JSON: {e}") from e

    if not isinstance(parsed, dict):
        raise RuntimeError(f"Secret '{secret_id}' JSON value must be an object/dictionary")

    return parsed


def get_secret_from_env() -> Dict[str, Any]:
    secret_id = os.environ["AWS_SECRET_ID"]
    region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")
    return retrieve_json_secret(secret_id, region)
